  // ================= one Orders inbox for every drop (and the old shop's orders) =================
  const ST = [["new", "New"], ["ready", "Ready"], ["picked", "Picked up"], ["cancelled", "Cancelled"]];
  // paying before pickup (server/droppay.js): Paid, Claimed (the buyer said I paid), Not paid, at pickup
  const PAYW = { paid: "Paid", claimed: "Claimed · they said they paid", unpaid: "Not paid", pickup: "Not paid · paying at pickup" };
  const cents$ = (c) => "$" + (c / 100).toFixed(c % 100 ? 2 : 0), owes = (x) => ["unpaid", "claimed", "pickup"].includes(x.pay);
  const paidLine = (os) => { const L = os.filter((x) => x.status !== "cancelled" && x.pay && x.pay !== "free" && x.pay !== "none"); if (!L.length) return "";
    const all = L.reduce((a, x) => a + x.total, 0), got = L.filter((x) => x.pay === "paid").reduce((a, x) => a + x.total, 0), cl = L.filter((x) => x.pay === "claimed").reduce((a, x) => a + x.total, 0);
    return `${cents$(got)} of ${cents$(all)} paid${cl ? ` · ${cents$(cl)} claimed` : ""}`; };
  const markPaid = async (x, on) => { await api("/api/host/drop-orders/" + encodeURIComponent(x.id) + "/paid", { paid: on }); x.pay = on ? "paid" : x.payChoice === "pickup" ? "pickup" : x.payAhead ? "unpaid" : "pickup"; if (!on && x.status === "paid") x.status = "new"; };
  /** At pickup: each window's orders with a box to tick, unpaid ones flagged with Mark paid right there. */
